              onValueChange={(value) => setNumberOfPeople(value[0])}
              min={2}
              max={10}
              step={1}
              className="mb-2"
            />
            <div className="flex justify-between text-gray-600">
              <span>2</span>
              <span>10</span>
            </div>
          </Card>
