            </div>
          </Card>

          {/* Credit Card */}
          <Card 
            className={`p-4 cursor-pointer transition-all ${
              selectedMethod === 'card' ? 'border-blue-500 bg-blue-50' : 'border-gray-200 hover:border-gray-300'
            }`}
            onClick={() => setSelectedMethod('card')}
          >
            <div className="flex items-center gap-3">
